static struct drm_framebuffer * bochs_user_framebuffer_create ( struct drm_device * dev , struct drm_file * filp , const struct drm_mode_fb_cmd2 * mode_cmd ) { struct drm_gem_object * obj ; struct bochs_framebuffer * bochs_fb ; int ret ; DRM_DEBUG_DRIVER ( "%dx%d, format %c%c%c%c\n" , mode_cmd -> width , mode_cmd -> height , ( mode_cmd -> pixel_format ) & 0xff , ( mode_cmd -> pixel_format >> 8 ) & 0xff , ( mode_cmd -> pixel_format >> 16 ) & 0xff , ( mode_cmd -> pixel_format >> 24 ) & 0xff ) ; if ( mode_cmd -> pixel_format != DRM_FORMAT_XRGB8888 ) { return ERR_PTR ( - ENOENT ) ; } obj = drm_gem_object_lookup ( filp , mode_cmd -> handles [ 0 ] ) ; if ( obj == NULL ) { return ERR_PTR ( - ENOENT ) ; } bochs_fb = kzalloc ( sizeof ( * bochs_fb ) , GFP_KERNEL ) ; if ( ! bochs_fb ) { drm_gem_object_unreference_unlocked ( obj ) ; return ERR_PTR ( - ENOMEM ) ; } ret = bochs_framebuffer_init ( dev , bochs_fb , mode_cmd , obj ) ; if ( ret ) { drm_gem_object_unreference_unlocked ( obj ) ; return ERR_PTR ( ret ) ; } return & bochs_fb -> base ; } 